const $=id=>document.getElementById(id);
const key={products:"iq_products",settings:"iq_settings",files:"iq_files",counts:"iq_counts"};
const PDF_HEADER="data:image/jpeg;base64,";
const AUTH_SIGNATURE="data:image/png;base64,";
const today=()=>new Date().toISOString().slice(0,10);
let products=JSON.parse(localStorage.getItem(key.products)||"[]");
let settings=JSON.parse(localStorage.getItem(key.settings)||"{}");
let files=JSON.parse(localStorage.getItem(key.files)||"[]");
let counts=JSON.parse(localStorage.getItem(key.counts)||'{"invoice":0,"quotation":0}');
let lines={invoice:[],quotation:[]};

function save(){localStorage.setItem(key.products,JSON.stringify(products));localStorage.setItem(key.settings,JSON.stringify(settings));localStorage.setItem(key.files,JSON.stringify(files));localStorage.setItem(key.counts,JSON.stringify(counts))}
function number(type){counts[type]=(counts[type]||0)+1;save();return (type==="invoice"?"INV-":"QUO-")+String(counts[type]).padStart(4,"0")}
function setupDoc(type){
  const prefix=type==="invoice"?"Proforma Invoice":"Quotation";
  $(type+"No").value=number(type);$(type+"Date").value=today();lines[type]=[];
  ["Customer","Phone","Address","Sales"].forEach(x=>$(type+x).value="");
  updateProducts(type);$(type+"Price").value="";renderLines(type);
}
function updateProducts(type){
  const sel=$(type+"Product"); const search=$(type+"Search").value.toLowerCase();
  sel.innerHTML='<option value="">Choose product</option>'+products.filter(p=>(p.name+" "+p.code).toLowerCase().includes(search)).map(p=>`<option value="${p.id}">${esc(p.name)} (${esc(p.code)}) - ₹${money(p.price)}</option>`).join("");
}
function syncSelectedPrice(type){
 const p=products.find(x=>x.id===$(type+"Product").value); const input=$(type+"Price"); if(input) input.value=p?Number(p.price||0):"";
}
function addLine(type){
  const p=products.find(x=>x.id===$(type+"Product").value); if(!p)return alert("Please choose a product.");
  const entered=Number($(type+"Price").value); const price=Number.isFinite(entered)&&entered>=0?entered:Number(p.price)||0;
  lines[type].push({id:p.id,qty:1,price}); renderLines(type); $(type+"Product").value=""; $(type+"Price").value="";
}
function renderLines(type){
 const wrap=$(type+"Lines");
 if(!lines[type].length){wrap.innerHTML='<div class="empty">No products added.</div>';renderTotals(type);return}
 const rows=lines[type].map((l,i)=>{const p=products.find(x=>x.id===l.id); if(!p)return '';
   const price=Number(l.price??p.price)||0, qty=Number(l.qty)||1, amount=price*qty, tax=amount*(Number(p.gst)||0)/100;
   return `<tr><td>${p.image?`<img class="line-product-image" src="${p.image}" alt="">`:''}<span>${esc(p.name)}<small>${esc(p.code)}</small></span></td><td><input class="price-edit" type="number" min="0" step="0.01" value="${price}" onchange="changePrice('${type}',${i},this.value)" title="Edit price / discount price"></td>${type==="invoice"?`<td><input class="qty" type="number" min="1" value="${qty}" onchange="changeQty('${type}',${i},this.value)"></td>`:""}<td>${p.gst}%</td><td>₹${money(amount)}</td><td>₹${money(tax)}</td><td>₹${money(amount+tax)}</td><td><button class="danger" onclick="removeLine('${type}',${i})">Delete</button></td></tr>`;
 }).join("");
 wrap.innerHTML=`<table class="line-table"><thead><tr><th>Product</th><th>Price</th>${type==="invoice"?"<th>Qty</th>":""}<th>GST</th><th>Amount</th><th>Tax</th><th>Total</th><th></th></tr></thead><tbody>${rows}</tbody></table>`;renderTotals(type)
}
function changeQty(type,i,v){lines[type][i].qty=Math.max(1,Number(v)||1);renderLines(type)}
function changePrice(type,i,v){const n=Number(v);lines[type][i].price=Number.isFinite(n)&&n>=0?n:0;renderLines(type)}
function removeLine(type,i){lines[type].splice(i,1);renderLines(type)}
function totals(type){let subtotal=0,tax=0;lines[type].forEach(l=>{let p=products.find(x=>x.id===l.id);if(!p)return;let a=(Number(l.price??p.price)||0)*(Number(l.qty)||1);subtotal+=a;tax+=a*(Number(p.gst)||0)/100});return {subtotal,tax,total:subtotal+tax}}
function renderTotals(type){let t=totals(type);$(type+"Totals").innerHTML=`<div class="total-row"><span>Subtotal</span><b>₹${money(t.subtotal)}</b></div><div class="total-row"><span>GST</span><b>₹${money(t.tax)}</b></div><div class="total-row grand"><span>Grand Total</span><b>₹${money(t.total)}</b></div>`}
function addProduct(){
 const name=$("pName").value.trim(),code=$("pCode").value.trim(),price=Number($("pPrice").value),qty=Number($("pQty").value)||0,gst=Number($("pGst").value)||0;
 if(!name||!code||!Number.isFinite(price))return alert("Enter product name, code and price.");
 const file=$("pImage").files[0];
 const finish=(image)=>{products.push({id:Date.now().toString(),name,code,price,qty,gst,image:image||""});save();["pName","pCode","pPrice","pQty"].forEach(id=>$(id).value="");$("pGst").value="18";$("pImage").value="";renderProducts();updateProducts("invoice");updateProducts("quotation")};
 if(file){const r=new FileReader();r.onload=()=>finish(r.result);r.readAsDataURL(file)}else finish("");
}
function renderProducts(){
 const q=$("productSearch").value.toLowerCase(); const arr=products.filter(p=>(p.name+" "+p.code).toLowerCase().includes(q));
 $("productList").innerHTML=arr.length?arr.map(p=>`<div class="product-row"><div class="product-list-name">${p.image?`<img src="${p.image}" alt="">`:''}<b>${esc(p.name)}</b></div><span>${esc(p.code)}</span><span>₹${money(p.price)}</span><span>Qty: ${p.qty}</span><span>GST: ${p.gst}%</span><button class="danger" onclick="deleteProduct('${p.id}')">Delete</button></div>`).join(""):'<div class="empty">No products added.</div>'
}
function deleteProduct(id){if(confirm("Delete this product?")){products=products.filter(p=>p.id!==id);save();renderProducts();updateProducts("invoice");updateProducts("quotation")}}
function saveSettings(){
 settings={name:$("sName").value,address:$("sAddress").value,phone:$("sPhone").value,email:$("sEmail").value,gst:$("sGst").value,website:$("sWebsite").value,bank:$("sBank").value,accountName:$("sAccountName").value,accountNo:$("sAccountNo").value,ifsc:$("sIfsc").value,branch:$("sBranch").value,upi:$("sUpi").value};save();$("settingsStatus").textContent="Settings saved.";setTimeout(()=>$("settingsStatus").textContent="",2000)
}
function loadSettings(){let s=settings;Object.entries({sName:"name",sAddress:"address",sPhone:"phone",sEmail:"email",sGst:"gst",sWebsite:"website",sBank:"bank",sAccountName:"accountName",sAccountNo:"accountNo",sIfsc:"ifsc",sBranch:"branch",sUpi:"upi"}).forEach(([id,k])=>$(id).value=s[k]||"")}
function makePDFHTML(type){
 const t=totals(type), s=settings, no=$(type+"No").value, date=$(type+"Date").value, isInvoice=type==="invoice";
 const rows=lines[type].map((l,i)=>{const p=products.find(x=>x.id===l.id);if(!p)return '';const price=Number(l.price??p.price)||0,qty=Number(l.qty)||1,amount=price*qty,tax=amount*(Number(p.gst)||0)/100;
   return `<tr><td class="num slno">${i+1}</td><td class="image-cell">${p.image?`<img class="pdf-product-image" src="${p.image}" alt="">`:'—'}</td><td><strong>${esc(p.name)}</strong><small>${esc(p.code)}</small></td><td class="num">₹${money(price)}</td>${isInvoice?`<td class="num">${qty}</td>`:""}<td class="num">${p.gst}%</td><td class="num">₹${money(amount)}</td><td class="num">₹${money(tax)}</td><td class="num">₹${money(amount+tax)}</td></tr>`}).join('');
 return `<div class="pdf-sheet"><div class="pdf-fixed-header"><img src="${PDF_HEADER}" alt="Company Header"></div><div class="pdf-content">
  <div class="pdf-doc-meta"><div class="pdf-doc-type">${isInvoice?"TAX INVOICE":"QUOTATION"}</div><div><span>${isInvoice?"PI No":"Quotation No"}</span><b>${esc(no)}</b></div><div><span>Date</span><b>${esc(date)}</b></div></div>
   <div class="pdf-customer-block"><div class="pdf-section-title">To</div><div class="customer-grid"><div><span>Customer Name</span><b>${esc($(type+"Customer").value||"—")}</b></div><div><span>Phone Number</span><b>${esc($(type+"Phone").value||"—")}</b></div><div><span>Address</span><b>${nl($(type+"Address").value||"—")}</b></div><div><span>Salesperson Name</span><b>${esc($(type+"Sales").value||"—")}</b></div></div></div>
   <table class="pdf-items"><thead><tr><th class="num slno">SL No.</th><th class="image-cell">Image</th><th>Product</th><th class="num">Price</th>${isInvoice?`<th class="num">Qty</th>`:""}<th class="num">GST</th><th class="num">Amount</th><th class="num">Tax</th><th class="num">Total</th></tr></thead><tbody>${rows}</tbody></table>
   <div class="pdf-summary"><div><span>Subtotal</span><b>₹${money(t.subtotal)}</b></div><div><span>GST / Tax</span><b>₹${money(t.tax)}</b></div><div class="pdf-grand"><span>Grand Total</span><b>₹${money(t.total)}</b></div></div>
   <div class="pdf-info-grid"><div class="pdf-info-box"><h3>Bank Details</h3><div><span>Bank</span><b>${esc(s.bank||"—")}</b></div><div><span>Account Name</span><b>${esc(s.accountName||"—")}</b></div><div><span>Account No.</span><b>${esc(s.accountNo||"—")}</b></div><div><span>IFSC</span><b>${esc(s.ifsc||"—")}</b></div><div><span>Branch</span><b>${esc(s.branch||"—")}</b></div><div><span>UPI</span><b>${esc(s.upi||"—")}</b></div></div><div class="pdf-info-box"><h3>Terms &amp; Conditions</h3><div>1. Payment Terms: Immediate Payment</div><div>2. Price: Indicates the cost of each item.</div><div>3. Taxes: As shown above.</div><div>4. Shipping Cost: Extra</div></div></div>
   <div class="pdf-signature-section"><img src="${AUTH_SIGNATURE}" alt="Authorised Signature"><div class="pdf-signature-label">Authorised Signature</div></div><div class="pdf-address-bottom"><div class="pdf-company-name">${esc(s.name||"")}</div><div>${s.phone?`Phone: ${esc(s.phone)}`:""}${s.email?` &nbsp; | &nbsp; Email: ${esc(s.email)}`:""}</div><div>${s.gst?`GSTIN: ${esc(s.gst)}`:""}${s.website?` &nbsp; | &nbsp; ${esc(s.website)}`:""}</div></div>
 </div><div class="pdf-fixed-footer"><span>${esc(s.name||"")}</span></div></div>`;
}
async function savePDF(type){
 if(!lines[type].length){alert("Add at least one product.");return}
 const area=$("pdfArea");area.innerHTML=makePDFHTML(type);const sheet=area.querySelector('.pdf-sheet'),content=area.querySelector('.pdf-content');
 const old={position:area.style.position,left:area.style.left,top:area.style.top,zIndex:area.style.zIndex,visibility:area.style.visibility,display:area.style.display,width:area.style.width};
 Object.assign(area.style,{position:'absolute',left:'0',top:'0',zIndex:'999999',visibility:'visible',display:'block',width:'794px'});
 try{
   if(!window.html2canvas||!window.jspdf?.jsPDF)throw new Error('PDF libraries not loaded');
   const imgs=[...sheet.querySelectorAll('img')];await Promise.all(imgs.map(img=>new Promise(r=>{if(img.complete&&img.naturalWidth)return r();const done=()=>{img.onload=null;img.onerror=null;r()};img.onload=done;img.onerror=done;setTimeout(done,8000)})));if(document.fonts?.ready)await document.fonts.ready;
   await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
   const canvas=await html2canvas(content,{scale:2,backgroundColor:'#fff',useCORS:true,allowTaint:false,logging:false,width:750,windowWidth:750,scrollX:0,scrollY:0});
   const pdf=new jspdf.jsPDF({orientation:'portrait',unit:'mm',format:'a4',compress:true});
   const pageW=210,pageH=297,headerH=27,footerH=11,side=6,contentW=198,contentH=pageH-headerH-footerH-2;
   const pxPerMm=canvas.width/contentW;const slicePx=Math.floor(contentH*pxPerMm);
   const pages=Math.max(1,Math.ceil(canvas.height/slicePx));
   for(let pg=0;pg<pages;pg++){
     if(pg)pdf.addPage();
     pdf.addImage(PDF_HEADER,'JPEG',side,0,contentW,headerH,undefined,'FAST');
     const sy=pg*slicePx, sh=Math.min(slicePx,canvas.height-sy);const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=sh;slice.getContext('2d').drawImage(canvas,0,sy,canvas.width,sh,0,0,canvas.width,sh);
     pdf.addImage(slice.toDataURL('image/jpeg',0.94),'JPEG',side,headerH,contentW,sh/pxPerMm,undefined,'FAST');
     pdf.setFillColor(32,41,54);pdf.rect(0,pageH-footerH,pageW,footerH,'F');pdf.setTextColor(255,255,255);pdf.setFont('helvetica','bold');pdf.setFontSize(7.5);pdf.text(String(settings.name||''),side,pageH-4);pdf.text('Thank you for your business',pageW-side,pageH-4,{align:'right'});
   }
   const no=$(type+"No").value||type.toUpperCase();pdf.save((no+'.pdf').replace(/[\\/:*?"<>|]/g,'-'));
   files.push({id:Date.now(),type,no,date:$(type+'Date').value,customer:$(type+'Customer').value,total:totals(type).total,html:area.innerHTML});save();renderFiles('all');
 }catch(err){console.error(err);alert('PDF could not be generated. Please check your internet connection and try again.');}
 finally{area.style.position=old.position;area.style.left=old.left||'-100000px';area.style.top=old.top;area.style.zIndex=old.zIndex;area.style.visibility=old.visibility||'hidden';area.style.display=old.display||'block';area.style.width=old.width||'794px'}
}
function renderFiles(filter){
 const arr=files.filter(f=>filter==="all"||f.type===filter).slice().reverse();
 $("fileList").innerHTML=arr.length?arr.map(f=>`<div class="file-row"><b>${f.type==="invoice"?"Invoice":"Quotation"} ${esc(f.no)}</b><span>${esc(f.customer||"")}</span><span>${esc(f.date)}</span><b>₹${money(f.total)}</b><button class="danger" onclick="deleteFile(${f.id})">Delete</button></div>`).join(""):'<div class="empty">No saved files yet. Saved PDFs are also downloaded to your computer.</div>'
}
function deleteFile(id){if(confirm("Delete saved record?")){files=files.filter(f=>f.id!==id);save();renderFiles("all")}}
function newDocument(type){setupDoc(type)}
function money(n){return Number(n||0).toLocaleString("en-IN",{minimumFractionDigits:2,maximumFractionDigits:2})}
function esc(v){return String(v??"").replace(/[&<>"']/g,m=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#039;"}[m]))}
function nl(v){return esc(v).replace(/\n/g,"<br>")}
document.querySelectorAll(".nav").forEach(btn=>btn.onclick=()=>{document.querySelectorAll(".nav").forEach(x=>x.classList.remove("active"));btn.classList.add("active");document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));$(btn.dataset.page).classList.add("active");$("pageTitle").textContent=btn.textContent;if(btn.dataset.page==="products")renderProducts();if(btn.dataset.page==="files")renderFiles("all");if(btn.dataset.page==="settings")loadSettings()});
$("invoiceSearch").oninput=()=>updateProducts("invoice");$("quotationSearch").oninput=()=>updateProducts("quotation");
setupDoc("invoice");setupDoc("quotation");loadSettings();renderProducts();renderFiles("all");
